# Lesson 3, part 5: extracting the yield when the bond is bought between two payment dates (Shay, 2026-11-16).
# The house method of the solutions booklet: rows of zero make the spacing of the table even, IRR gives the yield per row, a power converts it to a year.
assert round((1 + _fin.IRR([-98, 3, 0, 3, 0, 3, 0, 103])) ** 4 - 1, 4) == 0.0834
assert round((1 + _fin.IRR([-395, 0, 220, 0, 0, 210])) ** 3 - 1, 4) == 0.0769

# ================================================================ part 5
opener(5, 'חילוץ תשואה בין מועדים', 'שאלת החלק: מה עושים כשהמרווחים בטבלה אינם שווים?',
       ['הבעיה: IRR מניח מרווח זהה בין כל שתי שורות', 'הפתרון: שורות אפס שהופכות את הרשת לאחידה', 'שאלה 9 יחד, ושאלה 10 לבד', 'המרה לשנה לפי מספר השורות בשנה'], 35)


def _grid_chart():
    W, H = 1160, 330
    x0, step = 110, 130
    X = lambda q: x0 + q * step
    ya, yb = 92, 250
    p = []
    for y, lab in ((ya, 'הטבלה כפי שהיא'), (yb, 'אחרי שורות האפס')):
        p.append(f'<rect x="60" y="{y - 2}" width="{W - 100}" height="4" rx="2" fill="#1b2d55"/>')
    real = {0: ('31.3', '−98', '#e0454f'), 1: ('30.6', '3', '#0f9d90'), 3: ('31.12', '3', '#0f9d90'), 5: ('30.6', '3', '#0f9d90'), 7: ('31.12', '103', '#0f9d90')}
    top = ''
    for q, (d, v, col) in real.items():
        top += f'<circle cx="{X(q)}" cy="{ya}" r="9" fill="{col}"/>' + T(X(q), ya - 20, v, 19, col, 800) + T(X(q), ya + 32, d, 16, '#1b2d55', 600)
    p.append(GS(1, T(60, 34, 'הטבלה כפי שהיא: המחיר ב-31.3, והתשלומים כל חצי שנה', 18, '#1b2d55', 800, 'start') + top, 'pop'))
    gaps = ''.join(f'<path d="M{X(a) + 12} {ya + 46} H{X(b) - 12}" stroke="{c}" stroke-width="3"/>' + T((X(a) + X(b)) / 2, ya + 66, t, 16, c, 800) for a, b, t, c in ((0, 1, '3 חודשים', '#e0454f'), (1, 3, '6 חודשים', '#a86703'), (3, 5, '6 חודשים', '#a86703'), (5, 7, '6 חודשים', '#a86703')))
    p.append(GS(2, gaps, 'draw'))
    bot = ''
    for q in range(8):
        if q in real:
            d, v, col = real[q]
            bot += f'<circle cx="{X(q)}" cy="{yb}" r="9" fill="{col}"/>' + T(X(q), yb - 20, v, 19, col, 800)
        else:
            bot += f'<circle class="ring" cx="{X(q)}" cy="{yb}" r="11" fill="#fff" stroke="#6d4df2" stroke-width="4"/>' + T(X(q), yb - 20, '0', 20, '#6d4df2', 800)
    p.append(GS(3, T(60, yb - 60, 'אחרי שורות האפס: שורה בכל 3 חודשים', 18, '#1b2d55', 800, 'start') + bot, 'pop'))
    p.append(GS(4, ''.join(f'<path d="M{X(q) + 12} {yb + 24} H{X(q + 1) - 12}" stroke="#25a65f" stroke-width="3"/>' for q in range(7)) + BADGE((X(0) + X(7)) / 2, yb + 62, 'מרווח זהה, 3 חודשים: IRR מחזיר תשואה לרבעון', '#25a65f', fs=18), 'draw'))
    return DIAG(''.join(p), W, H, 'שורות אפס הופכות טבלה עם מרווחים לא שווים לרשת אחידה')


S('s-grid', 'העיקרון: שורות אפס', 'העיקרון לפני הגיליון: IRR דורש מרווח זהה בין השורות',
  '<div class="card diagw">' + _grid_chart() + '</div><div class="lsteps">' + ''.join(ST(i + 1, TX(x), cls='lstep') for i, x in enumerate([
      '<b>המצב.</b> קונים אג״ח ב-31.3 ב-98 ש״ח. התשלומים: 3 ש״ח בכל 30.6 ו-31.12, ובסוף 103.',
      '<b>הבעיה.</b> מהקנייה עד התשלום הראשון עוברים 3 חודשים, ואחר כך 6 חודשים בין תשלום לתשלום. IRR מניח מרווח זהה בין כל שתי שורות.',
      '<b>הפתרון.</b> מוסיפים שורות עם תזרים 0 בכל 30.9 ו-31.3. התזרימים לא השתנו, אבל עכשיו יש שורה בכל 3 חודשים.',
      '<b>התוצאה.</b> IRR על הרשת האחידה מחזיר תשואה לרבעון. לשנה ממירים בחזקת 4, כי יש 4 שורות בשנה.'])) + '</div>',
  kick=f'חלק {CUR[0]} · העיקרון')

